{"hypothesis":"Polishing both inferred reflection orientations before selecting a basin will improve the mean neighbour score by avoiding a poor symmetry projection on the perturbed start.","rationale":"The parent selects its reflection axis using only projection error, which need not predict the optimized packing quality for a perturbed candidate. A short optimization race between the same two projections preserves the orbit model and contact-release method while making basin selection depend on feasible radius sums.","source":"import time
from fractions import Fraction
import numpy as np
from scipy.optimize import minimize, linear_sum_assignment

PARAMS = {"release": (0.014, 0.002, 0.06), "contacts": (4, 3, 5), "polish": (80, 20, 180), "probe": (38, 15, 70)}


def canonical(obj):
    if 'circles' in obj:
        return obj
    rows = []
    for x, y, r, m in obj['orbits']:
        rows.append([x, y, r])
        if m == 2:
            rows.append([x, -y, r])
    return {'circles': rows}


def score(obj):
    try:
        a = np.asarray(canonical(obj)['circles'], dtype=float)
        if a.shape != (21, 3) or not np.isfinite(a).all() or np.any(a[:, 2] <= 0):
            return -float('inf')
        x, y, r = [[Fraction(float(v)) for v in a[:, k]] for k in range(3)]
        if max(u+v for u,v in zip(x,r))-min(u-v for u,v in zip(x,r))+max(u+v for u,v in zip(y,r))-min(u-v for u,v in zip(y,r)) > 2:
            return -float('inf')
        for i in range(21):
            for j in range(i):
                dx = a[i,0]-a[j,0]
                dy = a[i,1]-a[j,1]
                if np.sqrt(dx*dx+dy*dy) < a[i,2]+a[j,2]:
                    return -float('inf')
        return float(np.sum(a[:,2]))
    except (TypeError, ValueError, KeyError, OverflowError):
        return -float('inf')


class Finished(Exception):
    pass


def construct(params, seed, budget_s, init=None):
    start = time.monotonic()
    deadline = start + .69*budget_s
    rng = np.random.default_rng(seed)
    best = init
    best_score = score(init) if init is not None else -float('inf')

    def tick():
        if time.monotonic() >= deadline:
            raise Finished()

    if init is None:
        a = np.array([[2*(i%7), 2*(i//7), 1.] for i in range(21)], float)/10.00000000001
    else:
        try:
            a = np.asarray(canonical(init)['circles'], float).copy()
        except (ValueError, TypeError, KeyError):
            a = np.empty((0,3))
    if a.shape != (21,3) or not np.isfinite(a).all():
        a = np.array([[2*(i%7), 2*(i//7), 1.] for i in range(21)], float)/10.00000000001
    fallback = {'circles': a.tolist()}
    if score(fallback) > best_score:
        best, best_score = fallback, score(fallback)
    if best_score == -float('inf'):
        b = np.array([[2*(i%7), 2*(i//7), 1.] for i in range(21)], float)/10.00000000001
        best = {'circles': b.tolist()}
        best_score = score(best)
    lo = np.min(a[:,:2]-a[:,2,None],axis=0)
    hi = np.max(a[:,:2]+a[:,2,None],axis=0)
    a[:,:2] -= (lo+hi)/2
    projections = []
    for swap in (False, True):
        if time.monotonic() >= deadline:
            return best
        b = a.copy()
        if swap:
            b[:,[0,1]] = b[:,[1,0]]
        order = np.argsort(b[:,1])
        lower, singles, upper = order[:9], order[9:12], order[12:]
        reflected = b[lower].copy()
        reflected[:,1] *= -1
        cost = np.sum((b[upper,None,:]-reflected[None,:,:])**2,axis=2)
        u,v = linear_sum_assignment(cost)
        groups = [[b[k,0],0.,b[k,2]] for k in singles]
        error = float(np.sum(b[singles,1]**2))
        for p,q in zip(u,v):
            if time.monotonic() >= deadline:
                return best
            groups.append(((b[upper[p]]+reflected[q])/2).tolist())
            error += float(cost[p,q])
        projections.append((error,np.array(groups)))
    projections.sort(key=lambda t:t[0])
    gx, signs = [], []
    for g in range(12):
        if time.monotonic() >= deadline:
            return best
        gx.append(g)
        signs.append(0. if g < 3 else 1.)
        if g >= 3:
            gx.append(g)
            signs.append(-1.)
    gx, signs = np.array(gx), np.array(signs)
    X = np.zeros((21,34)); Y = X.copy(); R = X.copy()
    for k,g in enumerate(gx):
        if time.monotonic() >= deadline:
            return best
        X[k,g] = 1
        R[k,21+g] = 1
        if g >= 3:
            Y[k,12+g-3] = signs[k]
    pairs, seen = [], set()
    for i in range(21):
        if time.monotonic() >= deadline:
            return best
        for j in range(i):
            if time.monotonic() >= deadline:
                return best
            g,h = sorted((int(gx[i]),int(gx[j])))
            key = (g,h,int(signs[i]*signs[j]))
            if key not in seen:
                seen.add(key)
                pairs.append((i,j))
    pi,pj = np.array(pairs).T
    DX, DY, RS = X[pi]-X[pj], Y[pi]-Y[pj], R[pi]+R[pj]
    walls = np.zeros((36,34)); offsets = np.zeros(36)
    for g in range(12):
        if time.monotonic() >= deadline:
            return best
        walls[g,g] = 1
        walls[g,21+g] = -1
        walls[g,33] = .5
        walls[12+g,g] = -1
        walls[12+g,21+g] = -1
        walls[12+g,33] = .5
        walls[24+g,21+g] = -1
        walls[24+g,33] = -.5
        offsets[24+g] = 1
        if g >= 3:
            walls[24+g,12+g-3] = -1
    weights = np.array([1.]*3+[2.]*9)
    grad = np.zeros(34); grad[21:33] = -weights
    release = np.zeros(len(pi))
    bounds = [(-1.,1.)]*12+[(0.,1.)]*9+[(1e-6,.5)]*12+[(.1,1.9)]
    ii,jj = np.triu_indices(21,1)
    local_best = None
    local_score = -float('inf')

    def retain(v):
        nonlocal best,best_score,local_best,local_score
        tick()
        if not np.isfinite(v).all() or np.any(v[21:33] <= 0):
            return
        circles = np.column_stack((X@v,Y@v,R@v))
        dx = circles[ii,0]-circles[jj,0]
        dy = circles[ii,1]-circles[jj,1]
        ratio = np.min(np.sqrt(dx*dx+dy*dy)/(circles[ii,2]+circles[jj,2]))
        r = v[21:33]*min(1.,float(ratio))*(1.-8e-15)
        xx = v[:12]; yy = np.r_[np.zeros(3),v[12:21]]
        width = np.max(xx+r)-np.min(xx-r)
        height = 2*np.max(yy+r)
        scale = min(1.,2./(width+height))*(1.-8e-15)
        estimate = float(weights@r)*scale
        if estimate <= min(best_score,local_score):
            return
        obj = {'orbits': [[float(xx[g]*scale),float(yy[g]*scale),float(r[g]*scale),1 if g<3 else 2] for g in range(12)]}
        value = score(obj)
        if value > local_score:
            local_score,local_best = value,v.copy()
        if value > best_score:
            best,best_score = obj,value

    def fun(v):
        tick()
        return float(grad@v)

    def jac(v):
        tick()
        return grad

    def constraints(v):
        tick()
        dx,dy = DX@v,DY@v
        return np.r_[np.sqrt(dx*dx+dy*dy)-RS@v-release,walls@v+offsets]

    def derivatives(v):
        tick()
        dx,dy = DX@v,DY@v
        d = np.maximum(np.sqrt(dx*dx+dy*dy),1e-25)
        return np.vstack(((dx/d)[:,None]*DX+(dy/d)[:,None]*DY-RS,walls))

    def solve(v,iterations):
        tick()
        result = minimize(fun,v,jac=jac,bounds=bounds,method='SLSQP',constraints={'type':'ineq','fun':constraints,'jac':derivatives},callback=retain,options={'maxiter':iterations,'ftol':3e-14,'disp':False})
        retain(result.x)
        return result.x

    try:
        # Race both orientations; rank them by repaired, verified objective,
        # not by their distance from the input symmetry projection.
        racers = []
        for error,g0 in projections:
            tick()
            z = np.zeros(34)
            z[:12] = g0[:,0]
            z[12:21] = np.maximum(g0[3:,1],0)
            z[21:33] = np.maximum(g0[:,2],1e-6)
            z[33] = np.clip(np.max(g0[:,0]+g0[:,2])-np.min(g0[:,0]-g0[:,2]),.1,1.9)
            local_best,local_score = None,-float('inf')
            z = solve(z,int(params['probe']))
            racers.append((local_score,local_best.copy() if local_best is not None else z.copy()))
        racers.sort(key=lambda t:t[0],reverse=True)
        local_best,local_score = None,-float('inf')
        anchor = solve(racers[0][1],int(params['polish']))
        attempt = 0
        while time.monotonic() < deadline:
            tick()
            release[:] = 0
            dx,dy = DX@anchor,DY@anchor
            gaps = np.sqrt(dx*dx+dy*dy)-RS@anchor
            near = np.flatnonzero(gaps < .003)
            if len(near) < 3:
                break
            k = min(int(params['contacts']),len(near))
            chosen = rng.choice(near,k,replace=False)
            release[chosen] = float(params['release'])*rng.uniform(.65,1.35,k)*(1+.35*(attempt%3))
            displaced = solve(anchor.copy(),24)
            release[:] = 0
            recovered = solve(displaced,int(params['polish']))
            if float(grad@recovered) < float(grad@anchor)-1e-9 and np.min(constraints(recovered)) > -1e-8:
                anchor = recovered.copy()
            attempt += 1
    except (Finished, ValueError, FloatingPointError):
        pass
    return best
